def get_plant_phase_key(dap_val: int) -> str:
    if dap_val <= 14:
        return "semai"
    elif dap_val <= 29:
        return "vegetatif"
    elif dap_val <= 35:
        return "pra_panen"
    else:
        return "siap_panen"

def get_forecast_image_for_dap(dap_val: int, step_idx: int = 0) -> str:
    """
    Mengambil foto visualisasi kondisi tanaman pakcoy yang tepat 
    sesuai fase umur tanaman aktual (HST 1 s.d. 40).
    """
    if dap_val <= 14:
        phase = "semai"
        if dap_val <= 2:
            idx = 0
        elif dap_val <= 3:
            idx = 1
        elif dap_val <= 7:
            idx = 2
        else:
            idx = 3
    elif dap_val <= 29:
        phase = "vegetatif"
        if dap_val <= 15:
            idx = 0
        elif dap_val <= 18:
            idx = 1
        elif dap_val <= 23:
            idx = 2
        else:
            idx = 3
    elif dap_val <= 35:
        phase = "pra_panen"
        if dap_val <= 31:
            idx = 0
        elif dap_val <= 32:
            idx = 1
        elif dap_val <= 34:
            idx = 2
        else:
            idx = 3
    else:
        phase = "siap_panen"
        if dap_val <= 37:
            idx = 0
        elif dap_val <= 38:
            idx = 1
        elif dap_val <= 39:
            idx = 2
        else:
            idx = 3

    return FORECAST_IMAGES_BY_PHASE[phase][idx]
